const e={title:"TripReel - Gratis Reiseanimasjonsapp: Gjør Bilder til Vakre Videoer",description:"Lag fantastiske reisevideoer med animerte kart og flyruter. Gratis reiseanimasjonsapp med 3D-globe rutekartlegging. Gjør bildene dine til vakre reisevideoer automatisk. Personvern først, fungerer offline.",keywords:"reiseanimasjonsapp, reise-kart-animasjonsapp, reise-rute-animasjonsapp, fly-animasjonsapp, reise-videomaker, automatisk reisevideo, animert reisekart, flyrute-animasjon, reiseanimasjon, globe-animasjon, reise-gjennomgang-video, bilde til video, reise-høydepunkter, gratis reise-app, offline videomaker, personvern reise-app, kamerarull-video"},r={logoAlt:"TripReel-logo",appName:"TripReel",howItWorks:"Slik fungerer det",video:"Video",features:"Funksjoner",theApp:"Appen"},i={badge:"Gjør bilder om til reisehistorier",title1:"Bildebiblioteket ditt,",title2:"Fullt utnyttet",description:"TripReel lager automatisk flotte reisevideoer fra bildenes lokasjoner. Se reisene dine våkne til live med fantastiske animerte rutekart og flyveier på en 3D-globus, mens dataene dine forblir private og sikre.",secure:"100% sikkert",worksOffline:"Fungerer frakoblet",globeAlt:"TripReel globusanimasjon"},t={title:"Slik fungerer det",subtitle:"Tre enkle trinn for å lage den perfekte reisevideoen",step1:{title:"Gi tilgang til bilder",description:"Gi TripReel tilgang til bildebiblioteket ditt. Appen leser kun stedsmetadata, ingenting annet."},step2:{title:"Automatisk reisegjenkjenning",description:"TripReel analyserer stedsmetadata og finner intelligent reisene dine basert på datoer og lokasjoner."},step3:{title:"Generer videoen din",description:"Se reisen din utfolde seg på en vakker globusanimasjon, klar til å dele på sosiale medier."}},n={title:"Se magien skje",subtitle:"Se hvordan TripReel forvandler bildebiblioteket ditt til fantastiske reisevideoer",caption:"Slik vil den endelige reisevideoen din se ut"},a={title:"Alt du trenger",subtitle:"Kraftige funksjoner designet for moderne reisende",twoTap:{title:"Reisevideoer med to trykk",description:"Lag fantastiske reisevideoer fra bildebiblioteket ditt med bare to trykk. Ingen redigering nødvendig."},smartTrip:{title:"Smart reisegjenkjenning",description:"Finner og grupperer automatisk reisene dine ved å analysere datoer og stedsmetadata fra bildene dine."},globe:{title:"Vakker globusanimasjon",description:"Se reisen din våkne til live med en fantastisk 3D-globus som viser animerte reiseruter og flyveier rundt om i verden."},privacy:{title:"Personvern først",description:"Alt behandles på enheten din. Bildene dine forlater aldri telefonen. Fungerer i flymodus."},customStyles:{title:"Tilpassede stiler",description:"Velg mellom flere jordstiler og tilpasninger for å matche estetikken din og gjøre hver video unik."},manualControl:{title:"Manuell kontroll",description:"Du kan manuelt legge til helt nye reiser hvis stedstjenester ikke var aktivert på enheten din."}},s={title:"Kreative videoideer",subtitle:"La deg inspirere av hva du kan lage med TripReel. Fra korte helgeturer til helårs eventyr, lag fantastiske reisevideoer for hver reise.",description:"Enten du lager en reisekartsanimasjon, dokumenterer en flyreise eller lager et årssammendrag, gjør TripReel det enkelt å forvandle minnene dine til delbare videoer.",ideas:{yearRecap:{title:"2025 reisesammendrag",description:"Lag ditt årlige reisesammendrag for 2025 automatisk"},europeRoadTrip:{title:"Europa biltur",description:"Vis frem ditt europeiske eventyr med animerte rutekart"},southeastAsia:{title:"Sørøst-Asia-reise",description:"Visualiser ryggsekkturen din gjennom flere land"},japanRail:{title:"Japan togreise",description:"Lag kartvideoer av togrutene dine gjennom Japan"},crossCountry:{title:"På tvers av USA",description:"Gjør den amerikanske bilturen din om til en episk rutevideo"},islandHopping:{title:"Øyhopping",description:"Vis reisene dine fra øy til øy med fantastiske 3D-animasjoner"},worldTour:{title:"Verdensturné-montasje",description:"Flere reiser samlet i én fantastisk global reisevideo"},travelPlans:{title:"Reiseplaner 2026",description:"Visualiser og planlegg dine spennende reiseeventyr for 2026"},lifetimeTravel:{title:"Livslang reisehistorie",description:"Lag en video som viser alle reisene dine gjennom livet"},regionalExplorer:{title:"Regional oppdager",description:"Karlegg eventyrene dine gjennom stater, provinser og regioner"},festivalCircuit:{title:"Festivalkretsen",description:"Karlegg din musikkfestival- og eventreise"},bikeRoutes:{title:"Mine byturer",description:"Vis frem alle byeskapadene dine"}}},l={title:"Appen",subtitle:"Tilgjengelig nå i App Store",alt1:"Automatiske reisevideoer - Lag fantastiske videoer på sekunder",alt2:"Bildestedsgjenkjenning - Bruker bildenes metadata",alt3:"Reisegjenkjenning - Grupperer reisene dine automatisk",alt4:"Vakre jordvideoer - Globusanimasjon av reisen din",alt5:"Tilpassede stiler - Personaliser reisevideoene dine"},o={comingSoon:"Kommer snart",androidTitle:"Android-appen kommer snart!",androidMessage:'Android-versjonen er ikke tilgjengelig ennå, men kommer snart. Send meg en melding på <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> så gir jeg deg beskjed når den er klar!',gotIt:"Skjønner!"},d={title:"Ofte stilte spørsmål",subtitle:"Alt du trenger å vite om TripReel",q1:{question:"Kan jeg virkelig bruke appen fullt ut i flymodus?",answer:"Ja! For premiumbrukere kan appen brukes helt frakoblet i flymodus uten begrensninger. For ikke-premiumbrukere er noen funksjoner annonsestøttet, noe som kan kreve midlertidig aktivering av internett, men for premiumbrukere er det ingen annonser, og appen kan brukes fullt ut i flymodus."},q2:{question:"Jeg har oppgradert til Premium, hvordan kan jeg fjerne vannmerket?",answer:"Mange spør hvilken app som ble brukt til å lage disse videoene, så etter oppgradering til premium har du muligheten til å legge til en mindre versjon av vannmerket (bare med appnavnet) eller fjerne det helt hvis du ønsker."},q3:{question:"Er bildedataene mine trygge og private?",answer:"Absolutt! TripReel leser kun stedsmetadata fra bildene dine - vi får aldri tilgang til, lagrer eller sender det faktiske bildeinnholdet. All behandling skjer lokalt på enheten din, og ingen data forlater noensinne telefonen din. Du kan verifisere dette ved å bruke appen i flymodus - den fungerer perfekt frakoblet!"},q4:{question:"Hva om bildene mine ikke har stedsdata?",answer:"Ikke noe problem! Hvis stedstjenester ikke var aktivert når du tok bildene, kan du manuelt opprette reiser og legge til steder selv. Appen gir deg full kontroll til å tilpasse reisetidslinjen din."},q5:{question:"Hvordan gjenkjenner appen reisene mine automatisk?",answer:"TripReel analyserer stedsmetadata og tidsstempler fra bildene dine for intelligent å identifisere når og hvor du har reist. Den grupperer nærliggende steder og datoer sammen for automatisk å gjenkjenne reisene dine uten manuelt arbeid."},q6:{question:"Kan jeg tilpasse utseendet til videoene mine?",answer:"Ja! Du kan velge mellom flere jordstiler og tilpasse forskjellige aspekter av de animerte reisevideoene dine for å matche din personlige estetikk. Premiumbrukere får tilgang til ekstra ruteanimasjonsstiler, karttemaer og flyrutealternativer."},q7:{question:"Må jeg opprette en konto?",answer:"Ingen konto nødvendig! TripReel fungerer umiddelbart etter nedlasting. Det er ingen registrering, ingen pålogging, og ingen personlig informasjon nødvendig. Bare last ned appen og begynn å lage reisevideoene dine med en gang."},q8:{question:"Hvorfor mangler et sted fra reisen min?",answer:"Appen kan bare fungere med tilgjengelige data, så først og fremst trenger du minst noen bilder på det stedet. For det andre må du sørge for at du hadde stedsdata aktivert når du var der. For det tredje kan noen ganger dårlig GPS-mottak forårsake feil stedsdata. Hvis du har utelukket alt dette og stedet ditt fortsatt ikke vises, kan du manuelt legge til stedet fra Trips Overview > Edit-knappen. Bruk også Contact for å rapportere problemet."},q9:{question:"Hvor kan jeg dele den fantastiske videoen min?",answer:"Selvfølgelig kan du også dele den på alle sosiale plattformer. For å passe bedre til plattformen, tillater appen forskjellige bildeformater for videoene dine."},q10:{question:"Hvor kan jeg rapportere en feil?",answer:"Bare kontakt meg direkte på marian@qod.ee, og forklar kort hva problemet er."}},g={title:"E-poststøtte",description:"Hvis du har tilbakemeldinger eller støter på problemer, ta gjerne direkte kontakt med meg på denne e-posten, så vil jeg personlig lese og håndtere forespørselen din så raskt som mulig. Takk for at du bruker appen!",close:"Lukk"},p={default:{title:"🍪 Informasjonskapsler",message:"Vi bruker informasjonskapsler på TripReel-nettstedet for å forbedre opplevelsen din. Ingen personlige data samles inn.",accept:"Godta",decline:"Avvis",details:"Detaljer"},theme:{title:"🍪 Informasjonskapsler",message:"🌙 For å lagre temavalget ditt, må du godta nødvendige informasjonskapsler på TripReel-nettstedet. Uten dem kan ikke temavalget ditt lagres.",accept:"Godta",decline:"Avvis",details:"Detaljer"}},k={privacy:"App-personvernregler",cookies:"Nettstedinformasjonskapselregler",contact:"Kontakt",cookiePreferences:"Informasjonskapselinnstillinger",madeWith:"Laget med",forTravelers:"for reisende over hele verden",copyright:"© {{year}} TripReel."},m={title:"Klar til å dele reisen din?",description:"Last ned TripReel i dag og gjør bildebiblioteket ditt om til vakre reisevideoer med animerte kart og ruter. Eventyrene dine fortjener å bli feiret.",features:"Gratis å laste ned • Raskt og praktisk • Garantert personvern"},u={meta:e,header:r,hero:i,howItWorks:t,videoSection:n,features:a,videoIdeas:s,screenshots:l,appStore:o,faq:d,contact:g,cookieBanner:p,footer:k,cta:m};export{o as appStore,g as contact,p as cookieBanner,m as cta,u as default,d as faq,a as features,k as footer,r as header,i as hero,t as howItWorks,e as meta,l as screenshots,s as videoIdeas,n as videoSection};
